solution.solution.cpp:
#include <cstdint>
#include <format>
#include <string>

std::string describe(std::uint32_t code, int access, std::uint64_t address)
{
    switch (code)
    {
    case 0xC0000005u:
    {
        const char* verb{ access == 1 ? "writing" : access == 8 ? "executing" : "reading" };
        return std::format("access violation {} 0x{:X}{}", verb, address, address < 0x10000 ? " (null pointer)" : "");
    }
    case 0xC00000FDu: return "stack overflow";
    case 0xC0000094u: return "integer divide by zero";
    case 0xC0000409u: return "stack buffer overrun";
    case 0xE06D7363u: return "unhandled C++ exception";
    default: return std::format("exception 0x{:08X}", code);
    }
}

unitTests:
TEST("a null read") { CHECK_EQ(describe(0xC0000005u, 0, 0x10), std::string("access violation reading 0x10 (null pointer)")); }
TEST("a write elsewhere") { CHECK_EQ(describe(0xC0000005u, 1, 0x7FF6A1230000ull), std::string("access violation writing 0x7FF6A1230000")); }
TEST("executing") { CHECK_EQ(describe(0xC0000005u, 8, 0xDEADBEEF), std::string("access violation executing 0xDEADBEEF")); }
TEST("address zero") { CHECK_EQ(describe(0xC0000005u, 0, 0), std::string("access violation reading 0x0 (null pointer)")); }
TEST("just above the null zone") { CHECK_EQ(describe(0xC0000005u, 0, 0x10000), std::string("access violation reading 0x10000")); }
TEST("named codes") { CHECK_EQ(describe(0xC00000FDu, 0, 0), std::string("stack overflow")); CHECK_EQ(describe(0xC0000094u, 0, 0), std::string("integer divide by zero")); CHECK_EQ(describe(0xC0000409u, 0, 0), std::string("stack buffer overrun")); CHECK_EQ(describe(0xE06D7363u, 0, 0), std::string("unhandled C++ exception")); }
TEST("unknown codes") { CHECK_EQ(describe(0x80000003u, 0, 0), std::string("exception 0x80000003")); CHECK_EQ(describe(0x1u, 0, 0), std::string("exception 0x00000001")); }

